BEGIN
    UPDATE dbo.WorkoutSplits SET
        Name=N'Awesome Arms: 8 Weeks to Better Biceps and Triceps', Category=N'BroSplit', Level=N'Beginner', DurationDays=1,
        Description=N'Build better biceps and triceps in just 30-40 minutes. This awesome arm workout can be completed independently or added to your current program for extra gains.', HeroImageUrl=N'https://cdn.muscleandstrength.com/sites/default/files/fit-asian-man-doing-dumbbell-curl.jpg', IsSystemDefault=1, SortOrder=1028,
