        DaysPerWeek=7, ProgramDurationWeeks=8, MinSessionMinutes=15, MaxSessionMinutes=15, EquipmentRequired=N'Bands, Barbell, Bodyweight, Foam Roll, Kettle Bells, Other', TargetGender=N'Male & Female', WorkoutTypeLabel=N'Split', SourceCategoriesJson=N'["Women","Men","Beginner","At Home"]', CatalogRank=37
