    Title=N'Peanut Butter Banana Bulking Protein Shake Recipe', MealType=N'Snack', Description=N'A good protein shake for bulking. Ingredients include your favorite protein powder, banana and peanut butter.', CaloriesKcal=498, ProteinG=58, CarbsG=44, FatsG=11,
    SuggestedMonth=NULL, IsSystemDefault=1, SortOrder=10001, SourceUrl=N'https://www.muscleandstrength.com/recipes/peanut-butter-banana-bulking-protein-shake.html', ImageUrl=N'https://cdn.muscleandstrength.com/sites/default/files/field/feature-image/recipe/peanut-butter-banana-shake.jpg', ServingSuggestion=N'Makes one protein drink.', ContentText=N'Place ingredients into a blender and blend until smooth. You can also use whole milk and additional peanut butter, and turn this protein shake into a higher calorie weight gainer. Nutritional information for this recipe based on 2 scoops of whey protein blend and a medium banana. By using whole milk instead of skim milk, and by adding an additional tbsp of peanut butter, this shake would provide over 600 calories. Recipe provided by Jmango.', CategoriesJson=N'["Protein Shake Recipes"]', SourceMacrosJson=N'{"calories_kcal":"498","protein_g":"58","carbs_g":"44.3","fat_g":"11.2"}', ReadCount=705600
    WHERE MealSuggestionId=@ImportedMealSuggestionId;
DELETE FROM dbo.MealSuggestionIngredients WHERE MealSuggestionId=@ImportedMealSuggestionId;
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 1, N'8 oz skim milk');
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 2, N'1 banana');
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 3, N'1 tbsp peanut butter');
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 4, N'2 scoops of whey protein powder');
