IF @ImportedMealSuggestionId IS NULL
BEGIN
    SET @ImportedMealSuggestionId=NEWID();
    INSERT INTO dbo.MealSuggestions
        (MealSuggestionId, Title, MealType, Description, CaloriesKcal, ProteinG, CarbsG, FatsG, SuggestedMonth, IsSystemDefault, SortOrder, SourceUrl, ImageUrl, ServingSuggestion, ContentText, CategoriesJson, SourceMacrosJson, ReadCount)
    VALUES (@ImportedMealSuggestionId, N'Low Carb, High Protein Pizza Crust Recipe', N'Snack', N'An amazing pizza crust solution for you low-carbers or Paleo eaters. You won''t believe how great this tastes, and it''s incredibly easy to make!', 180, 11, 1, 14, NULL, 1, 10017, N'https://www.muscleandstrength.com/recipes/low-carb-high-protein-pizza-crust', N'https://cdn.muscleandstrength.com/sites/default/files/field/image/recipe/pizza-crust-450.jpg', N'This recipe makes one 9x13 pizza crust, or approximately 8 slices. Nutritional information is per slice.', N'Bring the cream cheese to room temperature. Preheat your oven to 350 degrees. Combine cream cheese, eggs and seasoning in a mixing bowl. Spray the bottom and sides of a 9x13 baking pan with a non-stick spray. Place the parmesan cheese evenly on the bottom of the baking pan, and then pour in the egg and cream cheese mixture. Bake for 15 to 25 minutes, or until the top of the crust starts to brown. Pull your crust out of the oven, top with your favorite ingredients, and place back in the oven to bake for 12 to 15 minutes. That''s it! You now have a low-carb pizza that tastes incredible.', N'["Low Carb Recipes"]', N'{"calories_kcal":"180","protein_g":"11","carbs_g":"1.3","fat_g":"14.5"}', 96500);
END
