INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 11, N'Optional: Can mix in 1/3 cup of dried cherries, or chopped pumpkin seeds, or mini chocolate chips');
