INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 1, N'In large bowl, combine Oats, Ground Chia, Hemp Seeds, Cacao Powder, Protein Powder, Cinnamon, and Sea Salt. Add in Almond Butter, Maple Syrup, Vanilla, and optional Mix-Ins, if using. Mix until just combined.');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 2, N'Scoop 1 Tbsp of mixture and roll between hands into ball. Place on cookie sheet. Repeat until all the mixture is used. Depending on the size, this should make about 20-28.');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 3, N'Place cookie sheet in refrigerator for about 30 minutes to set. Once chilled, store in airtight container in refrigerator for up to 1 week.');
GO

