    SET @ImportedMealSuggestionId=NEWID();
    INSERT INTO dbo.MealSuggestions
        (MealSuggestionId, Title, MealType, Description, CaloriesKcal, ProteinG, CarbsG, FatsG, SuggestedMonth, IsSystemDefault, SortOrder, SourceUrl, ImageUrl, ServingSuggestion, ContentText, CategoriesJson, SourceMacrosJson, ReadCount)
    VALUES (@ImportedMealSuggestionId, N'Bodybuilders Lean Beef Enchiladas Recipes', N'Dinner', N'Get your Mexican on with this beefy enchilada recipe! Low carb tortillas stuffed full of beef, beans and cheese make this very simple recipe a healthy way to satisfy your cravings!', 470, 52, 49, 14, NULL, 1, 10027, N'https://www.muscleandstrength.com/recipes/bodybuilders-lean-beef-enchiladas', N'https://cdn.muscleandstrength.com/sites/default/files/field/feature-image/recipe/beef_enchiladas_recipe.jpg', N'Entire Recipe is 1 Serving.', N'Preheat oven to 350 degrees Fahrenheit In a skillet over medium heat, saute ground beef until cooked Add in diced chiles, salt & pepper Transfer meat to a bowl and add in beans Spread half of the enchilada sauce on the bottom of an oven safe dish Divide the meat and bean mixture evenly down the middle of the 3 tortillas Sprinkle with half of the cheese Roll up tightly and place seam side down in the dish Spread remaining enchilada sauce on top Sprinkle with remaining cheese Bake for ~10-12 minutes Finish off with green onions, diced avocado or a dollop or greek yogurt, if desired Notes: * Beef can easily be substituted with ground turkey or chicken breast, shredded chicken breast, tofu or all beans', N'["High Protein Recipes","Dinner Recipes"]', N'{"calories_kcal":"470","protein_g":"52","carbs_g":"49","fat_g":"14"}', 64400);
END
