WHERE SourceUrl=N'https://www.muscleandstrength.com/recipes/turkey-sausage-frittata-egg-whites' OR (SourceUrl IS NULL AND Title=N'Turkey Sausage Frittata With Egg Whites Recipe');
IF @ImportedMealSuggestionId IS NULL
BEGIN
    SET @ImportedMealSuggestionId=NEWID();
    INSERT INTO dbo.MealSuggestions
        (MealSuggestionId, Title, MealType, Description, CaloriesKcal, ProteinG, CarbsG, FatsG, SuggestedMonth, IsSystemDefault, SortOrder, SourceUrl, ImageUrl, ServingSuggestion, ContentText, CategoriesJson, SourceMacrosJson, ReadCount)
    VALUES (@ImportedMealSuggestionId, N'Turkey Sausage Frittata With Egg Whites Recipe', N'Lunch', N'This is a healthy, high protein, low calorie and carb muscle building meal that can be eaten at any time of the day. All you need is broccoli, egg whites and turkey sausage.', 190, 26, 8, 7, NULL, 1, 10044, N'https://www.muscleandstrength.com/recipes/turkey-sausage-frittata-egg-whites', N'https://cdn.muscleandstrength.com/sites/default/files/field/image/recipe/sausage-450.jpg', N'Makes 6 servings.', N'Brown sausage in pan while thawing broccoli in the microwave. Mix together and season to taste. Place in 9x11 baking dish and pour egg whites over almost to cover. Bake at 350-375 for approximately 40 minutes.', N'["Low Carb Recipes","Lunch Recipes","Dinner Recipes"]', N'{"calories_kcal":"190","protein_g":"25.5","carbs_g":"8","fat_g":"7"}', 47400);
END
