    Title=N'Turkey Sausage Frittata With Egg Whites Recipe', MealType=N'Lunch', Description=N'This is a healthy, high protein, low calorie and carb muscle building meal that can be eaten at any time of the day. All you need is broccoli, egg whites and turkey sausage.', CaloriesKcal=190, ProteinG=26, CarbsG=8, FatsG=7,
    SuggestedMonth=NULL, IsSystemDefault=1, SortOrder=10044, SourceUrl=N'https://www.muscleandstrength.com/recipes/turkey-sausage-frittata-egg-whites', ImageUrl=N'https://cdn.muscleandstrength.com/sites/default/files/field/image/recipe/sausage-450.jpg', ServingSuggestion=N'Makes 6 servings.', ContentText=N'Brown sausage in pan while thawing broccoli in the microwave. Mix together and season to taste. Place in 9x11 baking dish and pour egg whites over almost to cover. Bake at 350-375 for approximately 40 minutes.', CategoriesJson=N'["Low Carb Recipes","Lunch Recipes","Dinner Recipes"]', SourceMacrosJson=N'{"calories_kcal":"190","protein_g":"25.5","carbs_g":"8","fat_g":"7"}', ReadCount=47400
    WHERE MealSuggestionId=@ImportedMealSuggestionId;
DELETE FROM dbo.MealSuggestionIngredients WHERE MealSuggestionId=@ImportedMealSuggestionId;
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 1, N'One Pound Turkey Sausage');
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 2, N'2 Bags Chopped Broccoli');
