INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 5, N'Pour mixture into dish and bake for ~45-50 minutes or until just set');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 6, N'Mixture will seem soft at first. Place in refrigerator to set for 4-6 hours or preferably, overnight.');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 7, N'Top with a drizzle of fresh maple syrup or whipped cream, if desired.');
