DECLARE @ImportedMealSuggestionId UNIQUEIDENTIFIER;
SELECT TOP (1) @ImportedMealSuggestionId=MealSuggestionId FROM dbo.MealSuggestions
WHERE SourceUrl=N'https://www.muscleandstrength.com/recipes/deep-dish-pizza-lasagna' OR (SourceUrl IS NULL AND Title=N'Deep Dish Pepperoni Pizza Lasagna Recipe');
IF @ImportedMealSuggestionId IS NULL
BEGIN
    SET @ImportedMealSuggestionId=NEWID();
    INSERT INTO dbo.MealSuggestions
        (MealSuggestionId, Title, MealType, Description, CaloriesKcal, ProteinG, CarbsG, FatsG, SuggestedMonth, IsSystemDefault, SortOrder, SourceUrl, ImageUrl, ServingSuggestion, ContentText, CategoriesJson, SourceMacrosJson, ReadCount)
    VALUES (@ImportedMealSuggestionId, N'Deep Dish Pepperoni Pizza Lasagna Recipe', N'Lunch', N'Looking for a healthy way to satisfy your craving for Italian food? Check out this pepperoni pizza lasagna recipe & get the best combo Italian has to offer!', 520, 57, 38, 17, NULL, 1, 10046, N'https://www.muscleandstrength.com/recipes/deep-dish-pizza-lasagna', N'https://cdn.muscleandstrength.com/sites/default/files/field/feature-image/recipe/pepperoni-pizza-lasagna.jpg', N'Makes 4 servings', N'Preheat oven to 350 degrees Combine cottage cheese, eggs, and ¼ cup pizza seasoning in a bowl. Mix with an electric mixer until creamy and smooth Spread ¼ cup pizza sauce on the bottom of a 9x13 in baking dish Layer 3 noodles on top of the sauce. Evenly spread 1/3 of cottage cheese mixture on top of the noodles. Spread a tiny bit of pizza sauce on top of the cottage cheese mixture. Sprinkle 1/4 of shredded cheese on top. Layer in 1/3 of your cooked ground turkey and top with 1/3 of pepperoni. Repeat layers two more times: 3 noodles, 1/3 cottage cheese, 1/4 mozzarella, 1/3 ground turkey, 1/3 pepperoni. Finish off with a final 1/4 of mozzarella and additional pepperoni, if desired. Cover and bake for 30 minutes or until cheese is melted and bubbly. Notes: *You can sub ground turkey for ground beef, sausage or chicken. **Nonfat cottage cheese can be replaced with ricotta to make a more traditional lasagna. Please not this will alter macronutrients listed below. *This can be made vegetarian friendly by swapping the ground turkey for soy crumble and tofurkey slices.', N'["High Protein Recipes","Lunch Recipes","Dinner Recipes"]', N'{"calories_kcal":"520","protein_g":"57","carbs_g":"38","fat_g":"17"}', 46500);
END
ELSE UPDATE dbo.MealSuggestions SET
    Title=N'Deep Dish Pepperoni Pizza Lasagna Recipe', MealType=N'Lunch', Description=N'Looking for a healthy way to satisfy your craving for Italian food? Check out this pepperoni pizza lasagna recipe & get the best combo Italian has to offer!', CaloriesKcal=520, ProteinG=57, CarbsG=38, FatsG=17,
    SuggestedMonth=NULL, IsSystemDefault=1, SortOrder=10046, SourceUrl=N'https://www.muscleandstrength.com/recipes/deep-dish-pizza-lasagna', ImageUrl=N'https://cdn.muscleandstrength.com/sites/default/files/field/feature-image/recipe/pepperoni-pizza-lasagna.jpg', ServingSuggestion=N'Makes 4 servings', ContentText=N'Preheat oven to 350 degrees Combine cottage cheese, eggs, and ¼ cup pizza seasoning in a bowl. Mix with an electric mixer until creamy and smooth Spread ¼ cup pizza sauce on the bottom of a 9x13 in baking dish Layer 3 noodles on top of the sauce. Evenly spread 1/3 of cottage cheese mixture on top of the noodles. Spread a tiny bit of pizza sauce on top of the cottage cheese mixture. Sprinkle 1/4 of shredded cheese on top. Layer in 1/3 of your cooked ground turkey and top with 1/3 of pepperoni. Repeat layers two more times: 3 noodles, 1/3 cottage cheese, 1/4 mozzarella, 1/3 ground turkey, 1/3 pepperoni. Finish off with a final 1/4 of mozzarella and additional pepperoni, if desired. Cover and bake for 30 minutes or until cheese is melted and bubbly. Notes: *You can sub ground turkey for ground beef, sausage or chicken. **Nonfat cottage cheese can be replaced with ricotta to make a more traditional lasagna. Please not this will alter macronutrients listed below. *This can be made vegetarian friendly by swapping the ground turkey for soy crumble and tofurkey slices.', CategoriesJson=N'["High Protein Recipes","Lunch Recipes","Dinner Recipes"]', SourceMacrosJson=N'{"calories_kcal":"520","protein_g":"57","carbs_g":"38","fat_g":"17"}', ReadCount=46500
    WHERE MealSuggestionId=@ImportedMealSuggestionId;
DELETE FROM dbo.MealSuggestionIngredients WHERE MealSuggestionId=@ImportedMealSuggestionId;
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 1, N'1½ lbs ground turkey breast, cooked*');
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 2, N'32 oz nonfat cottage cheese**');
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 3, N'2 large eggs');
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 4, N'2 - 12oz jars pizza sauce');
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 5, N'9 lasagna noodles, cooked');
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 6, N'1 package (5oz) reduced fat turkey pepperoni');
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 7, N'4 cups shredded reduced-fat mozzarella');
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 8, N'Pizza seasoning, to tase');
DELETE FROM dbo.MealSuggestionInstructions WHERE MealSuggestionId=@ImportedMealSuggestionId;
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 1, N'Preheat oven to 350 degrees');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 2, N'Combine cottage cheese, eggs, and ¼ cup pizza seasoning in a bowl. Mix with an electric mixer until creamy and smooth');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 3, N'Spread ¼ cup pizza sauce on the bottom of a 9x13 in baking dish');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 4, N'Layer 3 noodles on top of the sauce.');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 5, N'Evenly spread 1/3 of cottage cheese mixture on top of the noodles.');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 6, N'Spread a tiny bit of pizza sauce on top of the cottage cheese mixture. Sprinkle 1/4 of shredded cheese on top. Layer in 1/3 of your cooked ground turkey and top with 1/3 of pepperoni.');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 7, N'Repeat layers two more times: 3 noodles, 1/3 cottage cheese, 1/4 mozzarella, 1/3 ground turkey, 1/3 pepperoni. Finish off with a final 1/4 of mozzarella and additional pepperoni, if desired.');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 8, N'Cover and bake for 30 minutes or until cheese is melted and bubbly.');
