    VALUES (@ImportedMealSuggestionId, N'Mediterranean Rice Recipe', N'Lunch', N'Take that tired old can of tuna and turn it into a delicious dish that will keep you coming back for more!', 590, 30, 80, 10, NULL, 1, 10055, N'https://www.muscleandstrength.com/recipes/mediterranean-rice.html', N'https://cdn.muscleandstrength.com/sites/default/files/field/image/recipe/med-rice-450.jpg', N'Yields one serving.', N'Boil Basmati rice for aprox 15-20 minutes. Add rice to bowl. Cut up red onion into strips, add to rice. Drain tuna oil, add tuna to rice. Cut up avocado into small squares, add to rice. Squeeze lemon, add juice to rice. Add salt/pepper Ready to serve.', N'["Lunch Recipes","Dinner Recipes"]', N'{"calories_kcal":"590-600","protein_g":"30-32","carbs_g":"80","fat_g":"10-16"}', 42000);
