INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 1, N'Start by putting the pan on medium heat and grease/spray it lightly so that the meatballs doesn''t stick.');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 2, N'Grate or chop the onion finely.');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 3, N'In a large bowl, mix the grated onion with rest of the ingredients.');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 4, N'Make small balls out of the mixture, use a spoon to get a consistent size so that the meatballs cook equally fast (wet hands with cold water keeps the mixture from sticking to the hands).');
