DECLARE @ImportedMealSuggestionId UNIQUEIDENTIFIER;
SELECT TOP (1) @ImportedMealSuggestionId=MealSuggestionId FROM dbo.MealSuggestions
WHERE SourceUrl=N'https://www.muscleandstrength.com/recipes/kasein-protein-balls' OR (SourceUrl IS NULL AND Title=N'Chocolate Peanut Butter Kaged Muscle Kasein Balls');
IF @ImportedMealSuggestionId IS NULL
BEGIN
    SET @ImportedMealSuggestionId=NEWID();
    INSERT INTO dbo.MealSuggestions
        (MealSuggestionId, Title, MealType, Description, CaloriesKcal, ProteinG, CarbsG, FatsG, SuggestedMonth, IsSystemDefault, SortOrder, SourceUrl, ImageUrl, ServingSuggestion, ContentText, CategoriesJson, SourceMacrosJson, ReadCount)
    VALUES (@ImportedMealSuggestionId, N'Chocolate Peanut Butter Kaged Muscle Kasein Balls', N'Snack', N'Need the perfect before bed snack full of slow-digesting protein & healthy fats? These Chocolate Peanut Butter Kaged Muscle Protein Balls are perfect for you!', 125, 4, 6, 10, NULL, 1, 10081, N'https://www.muscleandstrength.com/recipes/kasein-protein-balls', N'https://cdn.muscleandstrength.com/sites/default/files/field/feature-image/recipe/kaged-muscle-feature.jpg', N'Makes 16 servings. 1 serving = 1 ball.', N'Place dates in food processor and process until smooth and creamy. Add peanut butter, vanilla extract, chocolate KASEIN protein powder and sea salt, and process for another 30 seconds. Next, add the cacao nibs and pulse to distribute. Transfer mixture to freezer and allow 30 minutes to set. Meanwhile, line a baking sheet with parchment paper. Remove mixture from freezer. Scoop heaping tablespoons of mixture and roll tight into 1-inch balls, and place on baking sheet. Transfer the sheet to the freezer and allow balls to set for 15 minutes. Meanwhile, combine dark chocolate and coconut oil in a double boiler and whisk until smooth. Set aside.* Remove baking sheet from freezer. Spoon a tablespoon of the chocolate mixture over each ball. Transfer baking sheet back to freezer and allow 15 minutes to set. In a double broiler, whisking together the peanut butter, coconut oil, and maple syrup over a double broiler until smooth. Lightly drizzle balls with mixture. Serve. *A double broiler is a set of two fitted saucepans that are stacked together with space between them. If you don’t have a double broiler, you can substitute by using a large saucepan filled with 2 inches of water and a steel-mixing bowl placed inside of it. Bring the water to a simmer before placing the mixing bowl with the ingredients in the pan.', N'["Protein Bar Recipes","High Protein Recipes","Snack Recipes","Vegetarian Recipes"]', N'{"calories_kcal":"125","protein_g":"4","carbs_g":"5.5","fat_g":"9.8"}', 29100);
END
ELSE UPDATE dbo.MealSuggestions SET
    Title=N'Chocolate Peanut Butter Kaged Muscle Kasein Balls', MealType=N'Snack', Description=N'Need the perfect before bed snack full of slow-digesting protein & healthy fats? These Chocolate Peanut Butter Kaged Muscle Protein Balls are perfect for you!', CaloriesKcal=125, ProteinG=4, CarbsG=6, FatsG=10,
    SuggestedMonth=NULL, IsSystemDefault=1, SortOrder=10081, SourceUrl=N'https://www.muscleandstrength.com/recipes/kasein-protein-balls', ImageUrl=N'https://cdn.muscleandstrength.com/sites/default/files/field/feature-image/recipe/kaged-muscle-feature.jpg', ServingSuggestion=N'Makes 16 servings. 1 serving = 1 ball.', ContentText=N'Place dates in food processor and process until smooth and creamy. Add peanut butter, vanilla extract, chocolate KASEIN protein powder and sea salt, and process for another 30 seconds. Next, add the cacao nibs and pulse to distribute. Transfer mixture to freezer and allow 30 minutes to set. Meanwhile, line a baking sheet with parchment paper. Remove mixture from freezer. Scoop heaping tablespoons of mixture and roll tight into 1-inch balls, and place on baking sheet. Transfer the sheet to the freezer and allow balls to set for 15 minutes. Meanwhile, combine dark chocolate and coconut oil in a double boiler and whisk until smooth. Set aside.* Remove baking sheet from freezer. Spoon a tablespoon of the chocolate mixture over each ball. Transfer baking sheet back to freezer and allow 15 minutes to set. In a double broiler, whisking together the peanut butter, coconut oil, and maple syrup over a double broiler until smooth. Lightly drizzle balls with mixture. Serve. *A double broiler is a set of two fitted saucepans that are stacked together with space between them. If you don’t have a double broiler, you can substitute by using a large saucepan filled with 2 inches of water and a steel-mixing bowl placed inside of it. Bring the water to a simmer before placing the mixing bowl with the ingredients in the pan.', CategoriesJson=N'["Protein Bar Recipes","High Protein Recipes","Snack Recipes","Vegetarian Recipes"]', SourceMacrosJson=N'{"calories_kcal":"125","protein_g":"4","carbs_g":"5.5","fat_g":"9.8"}', ReadCount=29100
    WHERE MealSuggestionId=@ImportedMealSuggestionId;
DELETE FROM dbo.MealSuggestionIngredients WHERE MealSuggestionId=@ImportedMealSuggestionId;
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 1, N'2 cups pitted & packed soft, sticky Medjool dates');
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 2, N'2 tbsp natural peanut butter');
