INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 4, N'Meanwhile, combine dark chocolate and coconut oil in a double boiler and whisk until smooth. Set aside.*');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 5, N'Remove baking sheet from freezer. Spoon a tablespoon of the chocolate mixture over each ball. Transfer baking sheet back to freezer and allow 15 minutes to set.');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 6, N'In a double broiler, whisking together the peanut butter, coconut oil, and maple syrup over a double broiler until smooth. Lightly drizzle balls with mixture. Serve.');
