DECLARE @ImportedMealSuggestionId UNIQUEIDENTIFIER;
SELECT TOP (1) @ImportedMealSuggestionId=MealSuggestionId FROM dbo.MealSuggestions
WHERE SourceUrl=N'https://www.muscleandstrength.com/recipes/pulled-bbq-chicken-potato-skins' OR (SourceUrl IS NULL AND Title=N'Pulled BBQ Chicken Potato Skins Recipe');
IF @ImportedMealSuggestionId IS NULL
BEGIN
    SET @ImportedMealSuggestionId=NEWID();
    INSERT INTO dbo.MealSuggestions
        (MealSuggestionId, Title, MealType, Description, CaloriesKcal, ProteinG, CarbsG, FatsG, SuggestedMonth, IsSystemDefault, SortOrder, SourceUrl, ImageUrl, ServingSuggestion, ContentText, CategoriesJson, SourceMacrosJson, ReadCount)
    VALUES (@ImportedMealSuggestionId, N'Pulled BBQ Chicken Potato Skins Recipe', N'Lunch', N'Need a snack for game time? Love finger food? Give this BBQ chicken potato skin recipe a try for a high protein spin on the delicious potato skin!', 327, 38, 28, 7, NULL, 1, 10086, N'https://www.muscleandstrength.com/recipes/pulled-bbq-chicken-potato-skins', N'https://cdn.muscleandstrength.com/sites/default/files/field/feature-image/recipe/bbq-chicken-potato-skin-recipe.jpg', N'Makes 4 Servings', N'Preheat oven to 425 degrees Line a baking sheet with foil Rinse potatoes and pierce with a fork Place potatoes on a baking sheet and bake for about 1 hour or until tender While potatoes are cooking, boil chicken for about 8-10 minutes or until cooked through When chicken is done, shred it by using 2 forks Toss the chicken with the BBQ sauce and set aside When potatoes are done, remove from the oven and allow to cool enough to handle Cut the potatoes in half and scoop out the middle, leaving a small bit of potato along the sides Evenly divide the pulled BBQ chicken among the potatoes Sprinkle with shredded cheddar cheese Return to the oven and bake an additional 20 minutes or until cheese is melted Finish off with extra BBQ sauce, if desired Notes: *You can swap the chicken breast and cheese for your favorite vegan or vegetarian friendly protein choice. **Please note that the macronutrients calculated below are using 1lb of potatoes including the center. The actual carb count will be less depending on the amount of center potato you remove.', N'["High Protein Recipes","Snack Recipes","Lunch Recipes","Dinner Recipes","BBQ/Grill Recipes"]', N'{"calories_kcal":"327","protein_g":"38","carbs_g":"28","fat_g":"7"}', 27200);
END
