DECLARE @ImportedMealSuggestionId UNIQUEIDENTIFIER;
SELECT TOP (1) @ImportedMealSuggestionId=MealSuggestionId FROM dbo.MealSuggestions
WHERE SourceUrl=N'https://www.muscleandstrength.com/recipes/cinnamon-chip-caramel-protein-bars' OR (SourceUrl IS NULL AND Title=N'Cinnamon Chip Caramel Protein Bars Recipe');
IF @ImportedMealSuggestionId IS NULL
BEGIN
    SET @ImportedMealSuggestionId=NEWID();
    INSERT INTO dbo.MealSuggestions
        (MealSuggestionId, Title, MealType, Description, CaloriesKcal, ProteinG, CarbsG, FatsG, SuggestedMonth, IsSystemDefault, SortOrder, SourceUrl, ImageUrl, ServingSuggestion, ContentText, CategoriesJson, SourceMacrosJson, ReadCount)
    VALUES (@ImportedMealSuggestionId, N'Cinnamon Chip Caramel Protein Bars Recipe', N'Snack', N'These tasty protein packed bars are the perfect snack when you''re on the go! Make a large batch during your Sunday meal prep and portion them out.', 275, 17, 33, 9, NULL, 1, 10091, N'https://www.muscleandstrength.com/recipes/cinnamon-chip-caramel-protein-bars', N'https://cdn.muscleandstrength.com/sites/default/files/field/feature-image/recipe/ccbars_feature.jpg', N'Makes 12 large bars.', N'Preheat oven to 350 degrees. Line a 9x13 inch pan with parchment paper (or coat well with non stick spray). Combine all dry ingredients in a bowl (protein, oats, cinnamon and salt). Mix together all wet ingredients (milk, almond butter, honey and extract). Combine wet and dry ingredients. Stir in cinnamon chips. Pour into baking dish. Bake for ~15 minutes. Remove from oven and allow to cool (bars will finish setting). Slice into desired size bars. Store in a sealed container. Notes: *You can reduce the carb and fat content by removing the cinnamon chips and adding an additional 1tsp of ground cinnamon. However, the chips really do make the bars!', N'["Protein Bar Recipes"]', N'{"calories_kcal":"275","protein_g":"17.1","carbs_g":"33.3","fat_g":"8.7"}', 26000);
END
ELSE UPDATE dbo.MealSuggestions SET
    Title=N'Cinnamon Chip Caramel Protein Bars Recipe', MealType=N'Snack', Description=N'These tasty protein packed bars are the perfect snack when you''re on the go! Make a large batch during your Sunday meal prep and portion them out.', CaloriesKcal=275, ProteinG=17, CarbsG=33, FatsG=9,
    SuggestedMonth=NULL, IsSystemDefault=1, SortOrder=10091, SourceUrl=N'https://www.muscleandstrength.com/recipes/cinnamon-chip-caramel-protein-bars', ImageUrl=N'https://cdn.muscleandstrength.com/sites/default/files/field/feature-image/recipe/ccbars_feature.jpg', ServingSuggestion=N'Makes 12 large bars.', ContentText=N'Preheat oven to 350 degrees. Line a 9x13 inch pan with parchment paper (or coat well with non stick spray). Combine all dry ingredients in a bowl (protein, oats, cinnamon and salt). Mix together all wet ingredients (milk, almond butter, honey and extract). Combine wet and dry ingredients. Stir in cinnamon chips. Pour into baking dish. Bake for ~15 minutes. Remove from oven and allow to cool (bars will finish setting). Slice into desired size bars. Store in a sealed container. Notes: *You can reduce the carb and fat content by removing the cinnamon chips and adding an additional 1tsp of ground cinnamon. However, the chips really do make the bars!', CategoriesJson=N'["Protein Bar Recipes"]', SourceMacrosJson=N'{"calories_kcal":"275","protein_g":"17.1","carbs_g":"33.3","fat_g":"8.7"}', ReadCount=26000
    WHERE MealSuggestionId=@ImportedMealSuggestionId;
DELETE FROM dbo.MealSuggestionIngredients WHERE MealSuggestionId=@ImportedMealSuggestionId;
