INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 7, N'Pour into baking dish.');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 8, N'Bake for ~15 minutes.');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 9, N'Remove from oven and allow to cool (bars will finish setting).');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 10, N'Slice into desired size bars.');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 11, N'Store in a sealed container.');
