DECLARE @ImportedMealSuggestionId UNIQUEIDENTIFIER;
SELECT TOP (1) @ImportedMealSuggestionId=MealSuggestionId FROM dbo.MealSuggestions
WHERE SourceUrl=N'https://www.muscleandstrength.com/recipes/crock-pot-turkey-meat-balls-green-pepper' OR (SourceUrl IS NULL AND Title=N'Crock Pot Turkey Meat Balls With Green Peppers Recipe');
IF @ImportedMealSuggestionId IS NULL
BEGIN
    SET @ImportedMealSuggestionId=NEWID();
    INSERT INTO dbo.MealSuggestions
        (MealSuggestionId, Title, MealType, Description, CaloriesKcal, ProteinG, CarbsG, FatsG, SuggestedMonth, IsSystemDefault, SortOrder, SourceUrl, ImageUrl, ServingSuggestion, ContentText, CategoriesJson, SourceMacrosJson, ReadCount)
    VALUES (@ImportedMealSuggestionId, N'Crock Pot Turkey Meat Balls With Green Peppers Recipe', N'Lunch', N'This spicy and bold low carb-friendly turkey and green pepper recipe yields eight to nine servings, containing 50 grams of muscle building protein and only 443 calories.', 443, 50, 18, 18, NULL, 1, 10097, N'https://www.muscleandstrength.com/recipes/crock-pot-turkey-meat-balls-green-pepper', N'https://cdn.muscleandstrength.com/sites/default/files/field/image/recipe/turkey-meatballs.jpg', N'You will get at least 8-9 large servings of 8 plus oz. each at about 443 calories each.', N'Cook cauliflower in microwave until very tender and can be chopped into fine pieces, set aside. Thaw green peppers in microwave and set aside. Mix turkey, eggs, coconut flour (if you use it), and onions if you are using them, worchester sauce, pepper, and all other seasonings you would like to use. Start rolling meatballs about this size of a golf ball and cover bottom of crock pot, layer some green peppers and cauliflower on them. Continue layering meat balls and peppers and cauliflower mix. After you get everything in take the cranberry sauce and run a knife through it to chop it up and distribute over meatballs. Pour the bottled chili sauce over everything. Cover and cook on high for 6 or 7 hours, depending on you crock pot. Total calories if you use 4 pounds of ground turkey 3,545. 50 grams protein in each 8 oz serving!', N'["High Protein Recipes","Low Carb Recipes","Lunch Recipes","Dinner Recipes"]', N'{"calories_kcal":"443","protein_g":"50","carbs_g":"18","fat_g":"18"}', 25000);
END
ELSE UPDATE dbo.MealSuggestions SET
    Title=N'Crock Pot Turkey Meat Balls With Green Peppers Recipe', MealType=N'Lunch', Description=N'This spicy and bold low carb-friendly turkey and green pepper recipe yields eight to nine servings, containing 50 grams of muscle building protein and only 443 calories.', CaloriesKcal=443, ProteinG=50, CarbsG=18, FatsG=18,
    SuggestedMonth=NULL, IsSystemDefault=1, SortOrder=10097, SourceUrl=N'https://www.muscleandstrength.com/recipes/crock-pot-turkey-meat-balls-green-pepper', ImageUrl=N'https://cdn.muscleandstrength.com/sites/default/files/field/image/recipe/turkey-meatballs.jpg', ServingSuggestion=N'You will get at least 8-9 large servings of 8 plus oz. each at about 443 calories each.', ContentText=N'Cook cauliflower in microwave until very tender and can be chopped into fine pieces, set aside. Thaw green peppers in microwave and set aside. Mix turkey, eggs, coconut flour (if you use it), and onions if you are using them, worchester sauce, pepper, and all other seasonings you would like to use. Start rolling meatballs about this size of a golf ball and cover bottom of crock pot, layer some green peppers and cauliflower on them. Continue layering meat balls and peppers and cauliflower mix. After you get everything in take the cranberry sauce and run a knife through it to chop it up and distribute over meatballs. Pour the bottled chili sauce over everything. Cover and cook on high for 6 or 7 hours, depending on you crock pot. Total calories if you use 4 pounds of ground turkey 3,545. 50 grams protein in each 8 oz serving!', CategoriesJson=N'["High Protein Recipes","Low Carb Recipes","Lunch Recipes","Dinner Recipes"]', SourceMacrosJson=N'{"calories_kcal":"443","protein_g":"50","carbs_g":"18","fat_g":"18"}', ReadCount=25000
    WHERE MealSuggestionId=@ImportedMealSuggestionId;
DELETE FROM dbo.MealSuggestionIngredients WHERE MealSuggestionId=@ImportedMealSuggestionId;
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 1, N'4 pounds lean ground turkey');
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 2, N'2 eggs');
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 3, N'2 tbsp coconut flour (optional)');
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 4, N'Chopped onions (optional, I don’t use onion)');
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 5, N'2 bags chopped green peppers');
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 6, N'1 bag cauliflower');
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 7, N'1 bottle chili sauce');
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 8, N'1 can jelled cranberry sauce');
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 9, N'½ cup Worcestershire sauce');
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 10, N'Cajun seasoning, black pepper, garlic salt, Lawry’s seasoned salt');
