WHERE SourceUrl=N'https://www.muscleandstrength.com/recipes/high-protein-tiramisu' OR (SourceUrl IS NULL AND Title=N'Simple & Creamy Protein Tiramisu Recipe');
IF @ImportedMealSuggestionId IS NULL
BEGIN
    SET @ImportedMealSuggestionId=NEWID();
    INSERT INTO dbo.MealSuggestions
        (MealSuggestionId, Title, MealType, Description, CaloriesKcal, ProteinG, CarbsG, FatsG, SuggestedMonth, IsSystemDefault, SortOrder, SourceUrl, ImageUrl, ServingSuggestion, ContentText, CategoriesJson, SourceMacrosJson, ReadCount)
    VALUES (@ImportedMealSuggestionId, N'Simple & Creamy Protein Tiramisu Recipe', N'Snack', N'Satisfy your sweet tooth with this classic Italian dessert. This tiramisu recipe is simple to make and packs a lot of protein aiding in some sweet gains!', 264, 28, 34, 3, NULL, 1, 10099, N'https://www.muscleandstrength.com/recipes/high-protein-tiramisu', N'https://cdn.muscleandstrength.com/sites/default/files/field/feature-image/recipe/tiramisu-feature.jpg', N'Makes 4 Servings', N'In a large bowl combine greek yogurt, protein powder, vanilla and stevia. Mix using an electric hand mixer for about 45-60 seconds or until protein is fully combined. Soak lady fingers, 1 at a time, in the coffee mixture and place on bottom of 8x8 baking dish. Repeat on bottom layer using 1/3 of the cookies. Top the cookies with 1/3 of greek yogurt mixture, 1 tsp ground cinnamon and 1 tsp cocoa powder. Repeat for 2 additional layer. Top the final layer of greek yogurt with shaved dark chocolate. Place in the refrigerator overnight to fully set. Enjoy with a dollop of whipped cream on top, if desired. Notes: *You can replace the liquid stevia with honey or any sweetener of choice. Please note that this will increase the carbohydrate content. Feel free to also leave out any additional sweetener if you are using a sweet protein powder.', N'["High Protein Recipes","Snack Recipes","Vegetarian Recipes"]', N'{"calories_kcal":"264","protein_g":"28","carbs_g":"34","fat_g":"3"}', 24700);
END
