DECLARE @ImportedMealSuggestionId UNIQUEIDENTIFIER;
SELECT TOP (1) @ImportedMealSuggestionId=MealSuggestionId FROM dbo.MealSuggestions
WHERE SourceUrl=N'https://www.muscleandstrength.com/recipes/honey-bbq-chicken-wings' OR (SourceUrl IS NULL AND Title=N'Honey BBQ Slow Cooker Chicken Wings Recipe');
IF @ImportedMealSuggestionId IS NULL
BEGIN
    SET @ImportedMealSuggestionId=NEWID();
    INSERT INTO dbo.MealSuggestions
        (MealSuggestionId, Title, MealType, Description, CaloriesKcal, ProteinG, CarbsG, FatsG, SuggestedMonth, IsSystemDefault, SortOrder, SourceUrl, ImageUrl, ServingSuggestion, ContentText, CategoriesJson, SourceMacrosJson, ReadCount)
    VALUES (@ImportedMealSuggestionId, N'Honey BBQ Slow Cooker Chicken Wings Recipe', N'Lunch', N'Want to watch the big game while eating wings, but don''t feel like leaving the house? Try out this honey BBQ wings recipe to get the best of both worlds!', 347, 21, 25, 18, NULL, 1, 10125, N'https://www.muscleandstrength.com/recipes/honey-bbq-chicken-wings', N'https://cdn.muscleandstrength.com/sites/default/files/field/feature-image/recipe/hone-bbq-wings-feature.jpg', N'Makes 12 servings. Macros will vary depending on BBQ sauce used.', N'Preheat oven to 450 degrees. Line a baking sheet with parchment paper. Place chicken wings on baking sheet and cook for 10 minutes. While chicken wings are baking, spray your slow cooker with nonstick spray. Add half the BBQ sauce to the bottom of the slow cooker. When chicken wings are done add them to the slow cooker. Top with the remaining BBQ sauce. Cook on high heat 2-3 hours or low heat 4-5 hours. Mix together cornstarch and water. 15 minutes before wings are done, add in the cornstarch mixture and toss to coat. Allow the wings to finish cooking and the sauce to thicken. Serve piping hot and dripping in thick, sweet BBQ sauce! Notes: *Use your favorite BBQ sauce *Macros will vary depending on BBQ sauce used', N'["High Protein Recipes","Snack Recipes","Lunch Recipes","Dinner Recipes"]', N'{"calories_kcal":"347","protein_g":"21","carbs_g":"25","fat_g":"18"}', 17700);
END
ELSE UPDATE dbo.MealSuggestions SET
    Title=N'Honey BBQ Slow Cooker Chicken Wings Recipe', MealType=N'Lunch', Description=N'Want to watch the big game while eating wings, but don''t feel like leaving the house? Try out this honey BBQ wings recipe to get the best of both worlds!', CaloriesKcal=347, ProteinG=21, CarbsG=25, FatsG=18,
    SuggestedMonth=NULL, IsSystemDefault=1, SortOrder=10125, SourceUrl=N'https://www.muscleandstrength.com/recipes/honey-bbq-chicken-wings', ImageUrl=N'https://cdn.muscleandstrength.com/sites/default/files/field/feature-image/recipe/hone-bbq-wings-feature.jpg', ServingSuggestion=N'Makes 12 servings. Macros will vary depending on BBQ sauce used.', ContentText=N'Preheat oven to 450 degrees. Line a baking sheet with parchment paper. Place chicken wings on baking sheet and cook for 10 minutes. While chicken wings are baking, spray your slow cooker with nonstick spray. Add half the BBQ sauce to the bottom of the slow cooker. When chicken wings are done add them to the slow cooker. Top with the remaining BBQ sauce. Cook on high heat 2-3 hours or low heat 4-5 hours. Mix together cornstarch and water. 15 minutes before wings are done, add in the cornstarch mixture and toss to coat. Allow the wings to finish cooking and the sauce to thicken. Serve piping hot and dripping in thick, sweet BBQ sauce! Notes: *Use your favorite BBQ sauce *Macros will vary depending on BBQ sauce used', CategoriesJson=N'["High Protein Recipes","Snack Recipes","Lunch Recipes","Dinner Recipes"]', SourceMacrosJson=N'{"calories_kcal":"347","protein_g":"21","carbs_g":"25","fat_g":"18"}', ReadCount=17700
    WHERE MealSuggestionId=@ImportedMealSuggestionId;
DELETE FROM dbo.MealSuggestionIngredients WHERE MealSuggestionId=@ImportedMealSuggestionId;
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 1, N'3lbs chicken wings');
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 2, N'1 bottle Honey BBQ Sauce*');
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 3, N'2 tbs cornstarch');
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 4, N'⅓ cup water');
DELETE FROM dbo.MealSuggestionInstructions WHERE MealSuggestionId=@ImportedMealSuggestionId;
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 1, N'Preheat oven to 450 degrees.');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 2, N'Line a baking sheet with parchment paper. Place chicken wings on baking sheet and cook for 10 minutes.');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 3, N'While chicken wings are baking, spray your slow cooker with nonstick spray. Add half the BBQ sauce to the bottom of the slow cooker.');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 4, N'When chicken wings are done add them to the slow cooker. Top with the remaining BBQ sauce.');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 5, N'Cook on high heat 2-3 hours or low heat 4-5 hours.');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 6, N'Mix together cornstarch and water. 15 minutes before wings are done, add in the cornstarch mixture and toss to coat.');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 7, N'Allow the wings to finish cooking and the sauce to thicken.');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 8, N'Serve piping hot and dripping in thick, sweet BBQ sauce!');
GO

