DECLARE @ImportedMealSuggestionId UNIQUEIDENTIFIER;
SELECT TOP (1) @ImportedMealSuggestionId=MealSuggestionId FROM dbo.MealSuggestions
WHERE SourceUrl=N'https://www.muscleandstrength.com/recipes/cinnamon-rolls' OR (SourceUrl IS NULL AND Title=N'Sweet & Simple Cinnamon Rolls Recipe');
IF @ImportedMealSuggestionId IS NULL
BEGIN
    SET @ImportedMealSuggestionId=NEWID();
    INSERT INTO dbo.MealSuggestions
        (MealSuggestionId, Title, MealType, Description, CaloriesKcal, ProteinG, CarbsG, FatsG, SuggestedMonth, IsSystemDefault, SortOrder, SourceUrl, ImageUrl, ServingSuggestion, ContentText, CategoriesJson, SourceMacrosJson, ReadCount)
    VALUES (@ImportedMealSuggestionId, N'Sweet & Simple Cinnamon Rolls Recipe', N'Breakfast', N'Do you love cinnamon rolls? Do you love gains? Want to incorporate cinnamon rolls that will fuel your "gain train" into your diet? You''ll love this recipe!', 297, 10, 35, 14, NULL, 1, 10134, N'https://www.muscleandstrength.com/recipes/cinnamon-rolls', N'https://cdn.muscleandstrength.com/sites/default/files/field/feature-image/recipe/cinnamon-rolls-feature.jpg', N'Makes 4 Servings. Can be served without frosting. Macros include frosting. (Macros without frosting are 278cal/7P/34C/14F)', N'Preheat oven to 400 degrees F Combine first 6 ingredients together in a bowl, cutting in butter until crumbly. Stir in milk, 1 tbsp. at a time until a dough forms Refrigerate dough for 20 minutes Lightly flour your counter and roll out dough into a large square. Spread with 1/2 melted coconut oil on top and sprinkle with coconut sugar and cinnamon. Roll up like a jelly roll. Cut into 4 even rolls. Place cut side down on a parchment line pan. Spread remaining melted coconut oil on top. Bake for ~ 15-18 minutes or until slightly golden. If making the protein frosting, combine all ingredients for frosting and drizzle on top of warm cinnamon rolls. Finish off with crushed pecans, if desired.', N'["High Protein Recipes","Snack Recipes","Vegetarian Recipes","Breakfast Recipes"]', N'{"calories_kcal":"297","protein_g":"10","carbs_g":"35","fat_g":"14"}', 16700);
END
ELSE UPDATE dbo.MealSuggestions SET
    Title=N'Sweet & Simple Cinnamon Rolls Recipe', MealType=N'Breakfast', Description=N'Do you love cinnamon rolls? Do you love gains? Want to incorporate cinnamon rolls that will fuel your "gain train" into your diet? You''ll love this recipe!', CaloriesKcal=297, ProteinG=10, CarbsG=35, FatsG=14,
    SuggestedMonth=NULL, IsSystemDefault=1, SortOrder=10134, SourceUrl=N'https://www.muscleandstrength.com/recipes/cinnamon-rolls', ImageUrl=N'https://cdn.muscleandstrength.com/sites/default/files/field/feature-image/recipe/cinnamon-rolls-feature.jpg', ServingSuggestion=N'Makes 4 Servings. Can be served without frosting. Macros include frosting. (Macros without frosting are 278cal/7P/34C/14F)', ContentText=N'Preheat oven to 400 degrees F Combine first 6 ingredients together in a bowl, cutting in butter until crumbly. Stir in milk, 1 tbsp. at a time until a dough forms Refrigerate dough for 20 minutes Lightly flour your counter and roll out dough into a large square. Spread with 1/2 melted coconut oil on top and sprinkle with coconut sugar and cinnamon. Roll up like a jelly roll. Cut into 4 even rolls. Place cut side down on a parchment line pan. Spread remaining melted coconut oil on top. Bake for ~ 15-18 minutes or until slightly golden. If making the protein frosting, combine all ingredients for frosting and drizzle on top of warm cinnamon rolls. Finish off with crushed pecans, if desired.', CategoriesJson=N'["High Protein Recipes","Snack Recipes","Vegetarian Recipes","Breakfast Recipes"]', SourceMacrosJson=N'{"calories_kcal":"297","protein_g":"10","carbs_g":"35","fat_g":"14"}', ReadCount=16700
    WHERE MealSuggestionId=@ImportedMealSuggestionId;
