INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 1, N'2 apples, cored and thinly sliced');
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 2, N'1 tbs coconut oil (or butter)');
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 3, N'¼ to ½ cup xylitol (or coconut sugar)*');
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 4, N'½ tbs ground cinnamon');
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 5, N'1 tbs cornstarch');
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 6, N'½ package frozen puff pastery sheets, thawed');
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 7, N'¼ cup egg whites');
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 8, N'toppings, optional');
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 9, N'Xylitol');
DELETE FROM dbo.MealSuggestionInstructions WHERE MealSuggestionId=@ImportedMealSuggestionId;
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 1, N'Preheat oven to 400 degrees F');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 2, N'Combine xylitol, cinnamon and cornstarch in a bowl. Set aside.');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 3, N'Melt coconut oil in a skillet over medium heat. Add in apples and mix well.');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 4, N'Allow to cook for 3-4 minutes. Add dry ingredients into apple mixture and mix until all apples are coated.');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 5, N'Allow to cook until sauce thickens.');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 6, N'Remove from heat and set aside.');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 7, N'Unfold pastry sheets and cut into four squares.');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 8, N'Spoon apples into center of each pastry sheet. Fold over from corner to corner, creating a triangle shape.');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 9, N'Press edges down with a fork to seal in apples.');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 10, N'Place on a parchment lined baking sheet.');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 11, N'Using a pastry brush, brush the top of each turnover with the egg whites and sprinkle with additional xylitol, if using.');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 12, N'Bake for about 20 minutes or until golden.');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 13, N'Allow to cool slightly before enjoying!');
GO

