WHERE SourceUrl=N'https://www.muscleandstrength.com/recipes/protein-french-toast-sticks' OR (SourceUrl IS NULL AND Title=N'Snickerdoodle Pecan Protein French Toast Sticks');
IF @ImportedMealSuggestionId IS NULL
BEGIN
    SET @ImportedMealSuggestionId=NEWID();
    INSERT INTO dbo.MealSuggestions
        (MealSuggestionId, Title, MealType, Description, CaloriesKcal, ProteinG, CarbsG, FatsG, SuggestedMonth, IsSystemDefault, SortOrder, SourceUrl, ImageUrl, ServingSuggestion, ContentText, CategoriesJson, SourceMacrosJson, ReadCount)
    VALUES (@ImportedMealSuggestionId, N'Snickerdoodle Pecan Protein French Toast Sticks', N'Breakfast', N'Wake up on the right side of the bed with this french toast sticks recipe! Full of protein, this tasty breakfast will help start your day on the right foot!', 348, 40, 29, 8, NULL, 1, 10146, N'https://www.muscleandstrength.com/recipes/protein-french-toast-sticks', N'https://cdn.muscleandstrength.com/sites/default/files/field/feature-image/recipe/french-toast-feature.jpg', N'Makes 2 servings (1 servings = 9 sticks)', N'Pre heat oven to 350 degrees F Line a baking sheet with parchment paper Cut each slice of bread into thirds Whisk together egg whites, milk, protein powder and additional cinnamon/sweetener, if using Coat each slice of bread in the egg mixture Place on parchment paper Bake for 9 minutes Flip and bake for an additional 9 minutes Serve with crushed pecans and any additional toppings, as desired Notes: *French Toast is best made with slightly stale bread *You can replace the vanilla egg whites with regular egg whites plus ½ tsp vanilla extract *Any flavor protein powder would work well in this recipe', N'["Snack Recipes","Vegetarian Recipes","Breakfast Recipes"]', N'{"calories_kcal":"348","protein_g":"40","carbs_g":"29","fat_g":"8"}', 15500);
END
