DECLARE @ImportedMealSuggestionId UNIQUEIDENTIFIER;
SELECT TOP (1) @ImportedMealSuggestionId=MealSuggestionId FROM dbo.MealSuggestions
WHERE SourceUrl=N'https://www.muscleandstrength.com/recipes/gluten-free-buckwheat-protein-crepes' OR (SourceUrl IS NULL AND Title=N'Easy Gluten-Free Buckwheat Protein Crepes Recipe');
IF @ImportedMealSuggestionId IS NULL
BEGIN
    SET @ImportedMealSuggestionId=NEWID();
    INSERT INTO dbo.MealSuggestions
        (MealSuggestionId, Title, MealType, Description, CaloriesKcal, ProteinG, CarbsG, FatsG, SuggestedMonth, IsSystemDefault, SortOrder, SourceUrl, ImageUrl, ServingSuggestion, ContentText, CategoriesJson, SourceMacrosJson, ReadCount)
    VALUES (@ImportedMealSuggestionId, N'Easy Gluten-Free Buckwheat Protein Crepes Recipe', N'Breakfast', N'These come together really fast and can be filled with either a savory or a sweet filling. They are perfect for breakfast or dinner and are filled with protein.', 243, 16, 23, 10, NULL, 1, 10148, N'https://www.muscleandstrength.com/recipes/gluten-free-buckwheat-protein-crepes', N'https://cdn.muscleandstrength.com/sites/default/files/field/image/recipe/crepes-450.jpg', N'Makes 10-12 ten inch crepes. Serving suggestion: 2 crepes. Nutritional information if without the savory filling. With the savory filling the nutrition information is: Calories: 496 Fat: 25g Carbohydrates: 31g Protein: 37g', N'Savory Filling Option (enough for 2 crepes): 3 eggs, scrambled ½ cup red or yellow bell pepper, lightly sautéed in coconut oil for 5 minutes 1 cup Spinach, lightly sautéed in coconut oil for 2 minutes Instructions: In blender, add Almond Milk, Cottage Cheese (or additional Almond Milk), Sea Salt, Eggs and Egg white. Blend on high for 45 seconds. Add Buckwheat flour and blend another 10 seconds. Refrigerate mixture in blender container for 45 minutes before using. After 45 minutes, remove container, add Coconut Oil (in liquid form) and blend right away before it can solidify in the cold batter. Heat your nonstick skillet over medium heat, just barely enough to make the batter slightly sizzle. Do not let pan get to hot or batter will not spread. Watch how first crepe spreads. You may need to decrease or increase heat. Add ¼ cup batter to the pan and swirl pan to distribute it evenly in a thin layer across the bottom. Cook just until the bottom is browned and can easily be flipped. Cook other side for about 20-30 seconds. Save extra crepes by using wax paper to separate each. Wrap and freeze for later. Tip: Fill crepes with scrambled egg and veggie/green mixture for savory. Or fill with fruit spread of choice and cottage cheese for sweet mixture. These are forgiving and can be filled with a variety of different options. Makes 10 – 12 (10 inch) crepes.', N'["Breakfast Recipes"]', N'{"calories_kcal":"243","protein_g":"16","carbs_g":"23","fat_g":"10"}', 15300);
END
ELSE UPDATE dbo.MealSuggestions SET
    Title=N'Easy Gluten-Free Buckwheat Protein Crepes Recipe', MealType=N'Breakfast', Description=N'These come together really fast and can be filled with either a savory or a sweet filling. They are perfect for breakfast or dinner and are filled with protein.', CaloriesKcal=243, ProteinG=16, CarbsG=23, FatsG=10,
    SuggestedMonth=NULL, IsSystemDefault=1, SortOrder=10148, SourceUrl=N'https://www.muscleandstrength.com/recipes/gluten-free-buckwheat-protein-crepes', ImageUrl=N'https://cdn.muscleandstrength.com/sites/default/files/field/image/recipe/crepes-450.jpg', ServingSuggestion=N'Makes 10-12 ten inch crepes. Serving suggestion: 2 crepes. Nutritional information if without the savory filling. With the savory filling the nutrition information is: Calories: 496 Fat: 25g Carbohydrates: 31g Protein: 37g', ContentText=N'Savory Filling Option (enough for 2 crepes): 3 eggs, scrambled ½ cup red or yellow bell pepper, lightly sautéed in coconut oil for 5 minutes 1 cup Spinach, lightly sautéed in coconut oil for 2 minutes Instructions: In blender, add Almond Milk, Cottage Cheese (or additional Almond Milk), Sea Salt, Eggs and Egg white. Blend on high for 45 seconds. Add Buckwheat flour and blend another 10 seconds. Refrigerate mixture in blender container for 45 minutes before using. After 45 minutes, remove container, add Coconut Oil (in liquid form) and blend right away before it can solidify in the cold batter. Heat your nonstick skillet over medium heat, just barely enough to make the batter slightly sizzle. Do not let pan get to hot or batter will not spread. Watch how first crepe spreads. You may need to decrease or increase heat. Add ¼ cup batter to the pan and swirl pan to distribute it evenly in a thin layer across the bottom. Cook just until the bottom is browned and can easily be flipped. Cook other side for about 20-30 seconds. Save extra crepes by using wax paper to separate each. Wrap and freeze for later. Tip: Fill crepes with scrambled egg and veggie/green mixture for savory. Or fill with fruit spread of choice and cottage cheese for sweet mixture. These are forgiving and can be filled with a variety of different options. Makes 10 – 12 (10 inch) crepes.', CategoriesJson=N'["Breakfast Recipes"]', SourceMacrosJson=N'{"calories_kcal":"243","protein_g":"16","carbs_g":"23","fat_g":"10"}', ReadCount=15300
    WHERE MealSuggestionId=@ImportedMealSuggestionId;
DELETE FROM dbo.MealSuggestionIngredients WHERE MealSuggestionId=@ImportedMealSuggestionId;
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 1, N'1 cup Almond Milk, Unsweetened');
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 2, N'½ cup Cottage Cheese (or additional ½ cup Almond Milk for Dairy-Free version)');
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 3, N'½ teaspoon Sea Salt');
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 4, N'2 Large Eggs');
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 5, N'2 Egg Whites');
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 6, N'1 ¼ cup Buckwheat Flour');
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 7, N'2 tablespoons Coconut Oil, in liquid form');
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 8, N'Coconut Oil for cooking');
DELETE FROM dbo.MealSuggestionInstructions WHERE MealSuggestionId=@ImportedMealSuggestionId;
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 1, N'In blender, add Almond Milk, Cottage Cheese (or additional Almond Milk), Sea Salt, Eggs and Egg white. Blend on high for 45 seconds. Add Buckwheat flour and blend another 10 seconds. Refrigerate mixture in blender container for 45 minutes before using.');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 2, N'After 45 minutes, remove container, add Coconut Oil (in liquid form) and blend right away before it can solidify in the cold batter.');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 3, N'Heat your nonstick skillet over medium heat, just barely enough to make the batter slightly sizzle. Do not let pan get to hot or batter will not spread. Watch how first crepe spreads. You may need to decrease or increase heat.');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 4, N'Add ¼ cup batter to the pan and swirl pan to distribute it evenly in a thin layer across the bottom. Cook just until the bottom is browned and can easily be flipped. Cook other side for about 20-30 seconds. Save extra crepes by using wax paper to separate each. Wrap and freeze for later.');
