DECLARE @ImportedMealSuggestionId UNIQUEIDENTIFIER;
SELECT TOP (1) @ImportedMealSuggestionId=MealSuggestionId FROM dbo.MealSuggestions
WHERE SourceUrl=N'https://www.muscleandstrength.com/recipe/baked-salmon-roasted-potatoes' OR (SourceUrl IS NULL AND Title=N'Baked Salmon With Herb Roasted Potatoes & Steamed Broccoli Recipe');
IF @ImportedMealSuggestionId IS NULL
BEGIN
    SET @ImportedMealSuggestionId=NEWID();
    INSERT INTO dbo.MealSuggestions
        (MealSuggestionId, Title, MealType, Description, CaloriesKcal, ProteinG, CarbsG, FatsG, SuggestedMonth, IsSystemDefault, SortOrder, SourceUrl, ImageUrl, ServingSuggestion, ContentText, CategoriesJson, SourceMacrosJson, ReadCount)
    VALUES (@ImportedMealSuggestionId, N'Baked Salmon With Herb Roasted Potatoes & Steamed Broccoli Recipe', N'Dinner', N'This flavor-packed bulking meal from Nick Ludlow turns boring old fish, potatoes and broccoli into a feast. Recipe contains 60 grams of protein and 895 calories.', 895, 60, 85, 35, NULL, 1, 10153, N'https://www.muscleandstrength.com/recipe/baked-salmon-roasted-potatoes', N'https://cdn.muscleandstrength.com/sites/default/files/field/image/recipe/recipe-450.jpg', N'This recipe will provide 2 servings. Feel free to sub out any of the three components based on your taste preferences and dietary requirements.', N'Preheat the oven to 400 degrees Fahrenheit. Place tinfoil on a shallow cookie sheet with raised edges. Drizzle and evenly spread 1 tbsp of olive/coconut oil on to the cookie sheet. Place the 1lb wild-caught salmon on the cookie sheet. In a small bowl, combine rosemary, basil, oregano, salt, and black pepper. Sprinkle half of this mixture on top of the salmon. Add red pepper flakes and lemon juice. In a large bowl toss the red potatoes diced in to bite-sized pieces with 2 tbsp of olive oil/coconut oil, garlic powder and the remaining seasoning mixture used for the salmon. Place the potatoes on a tin foil-lined cookie sheet with raised edges. Once preheated, place the salmon in the middle rack of the oven and the potatoes in the rack below the salmon at the same time. Allow both the cook for 25 minutes. After 25 minutes remove the salmon, decrease the oven temperature to 375 degrees Fahrenheit and continue baking the potatoes for 5 minutes. While the salmon and potatoes are cooking, trim and chop the 3 heads of fresh broccoli in to bite-sized pieces. Place the broccoli in 1 inch of boiling water and simmer in a covered saucepan on medium heat for 5 to 8 minutes. Try to time the broccoli so that it’s finished right when the potatoes finish cooking. I typically plate the salmon first and then add the roasted potatoes followed by the steam broccoli. Only after I plate all three items do finish the broccoli with a drizzle of Sriracha.', N'["Dinner Recipes"]', N'{"calories_kcal":"895","protein_g":"60","carbs_g":"85","fat_g":"35"}', 14600);
END
ELSE UPDATE dbo.MealSuggestions SET
    Title=N'Baked Salmon With Herb Roasted Potatoes & Steamed Broccoli Recipe', MealType=N'Dinner', Description=N'This flavor-packed bulking meal from Nick Ludlow turns boring old fish, potatoes and broccoli into a feast. Recipe contains 60 grams of protein and 895 calories.', CaloriesKcal=895, ProteinG=60, CarbsG=85, FatsG=35,
    SuggestedMonth=NULL, IsSystemDefault=1, SortOrder=10153, SourceUrl=N'https://www.muscleandstrength.com/recipe/baked-salmon-roasted-potatoes', ImageUrl=N'https://cdn.muscleandstrength.com/sites/default/files/field/image/recipe/recipe-450.jpg', ServingSuggestion=N'This recipe will provide 2 servings. Feel free to sub out any of the three components based on your taste preferences and dietary requirements.', ContentText=N'Preheat the oven to 400 degrees Fahrenheit. Place tinfoil on a shallow cookie sheet with raised edges. Drizzle and evenly spread 1 tbsp of olive/coconut oil on to the cookie sheet. Place the 1lb wild-caught salmon on the cookie sheet. In a small bowl, combine rosemary, basil, oregano, salt, and black pepper. Sprinkle half of this mixture on top of the salmon. Add red pepper flakes and lemon juice. In a large bowl toss the red potatoes diced in to bite-sized pieces with 2 tbsp of olive oil/coconut oil, garlic powder and the remaining seasoning mixture used for the salmon. Place the potatoes on a tin foil-lined cookie sheet with raised edges. Once preheated, place the salmon in the middle rack of the oven and the potatoes in the rack below the salmon at the same time. Allow both the cook for 25 minutes. After 25 minutes remove the salmon, decrease the oven temperature to 375 degrees Fahrenheit and continue baking the potatoes for 5 minutes. While the salmon and potatoes are cooking, trim and chop the 3 heads of fresh broccoli in to bite-sized pieces. Place the broccoli in 1 inch of boiling water and simmer in a covered saucepan on medium heat for 5 to 8 minutes. Try to time the broccoli so that it’s finished right when the potatoes finish cooking. I typically plate the salmon first and then add the roasted potatoes followed by the steam broccoli. Only after I plate all three items do finish the broccoli with a drizzle of Sriracha.', CategoriesJson=N'["Dinner Recipes"]', SourceMacrosJson=N'{"calories_kcal":"895","protein_g":"60","carbs_g":"85","fat_g":"35"}', ReadCount=14600
    WHERE MealSuggestionId=@ImportedMealSuggestionId;
DELETE FROM dbo.MealSuggestionIngredients WHERE MealSuggestionId=@ImportedMealSuggestionId;
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 1, N'1lb of wild-caught salmon');
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 2, N'3 heads of fresh broccoli');
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 3, N'4 cups of diced red potatoes');
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 4, N'½ large lemon or 1.5 tbsp lemon juice');
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 5, N'3 tbsp of olive oil or coconut oil');
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 6, N'2 tbsp of Sriracha');
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 7, N'1 tbsp of dried rosemary');
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 8, N'1 tbsp of dried basil');
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 9, N'1 tbsp oregano');
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 10, N'2 tsp of garlic powder');
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 11, N'2 tsp of salt');
