DECLARE @ImportedMealSuggestionId UNIQUEIDENTIFIER;
SELECT TOP (1) @ImportedMealSuggestionId=MealSuggestionId FROM dbo.MealSuggestions
WHERE SourceUrl=N'https://www.muscleandstrength.com/recipes/churro-protein-scones' OR (SourceUrl IS NULL AND Title=N'High Protein Churro Scones Recipe');
IF @ImportedMealSuggestionId IS NULL
BEGIN
    SET @ImportedMealSuggestionId=NEWID();
    INSERT INTO dbo.MealSuggestions
        (MealSuggestionId, Title, MealType, Description, CaloriesKcal, ProteinG, CarbsG, FatsG, SuggestedMonth, IsSystemDefault, SortOrder, SourceUrl, ImageUrl, ServingSuggestion, ContentText, CategoriesJson, SourceMacrosJson, ReadCount)
    VALUES (@ImportedMealSuggestionId, N'High Protein Churro Scones Recipe', N'Breakfast', N'Can''t find the perfect high protein snack to pair with your morning coffee? Try out this protein churro scone recipe as your coffee''s sweet counterpart.', 266, 12, 32, 10, NULL, 1, 10159, N'https://www.muscleandstrength.com/recipes/churro-protein-scones', N'https://cdn.muscleandstrength.com/sites/default/files/field/feature-image/recipe/churro-protein-scone-thumb.jpg', N'Makes 8 Servings', N'Preheat oven to 400 degrees F Line a baking sheet with parchment paper Combine oat flour, protein powder, baking powder, salt and 2 tsp cinnamon in a bowl Add frozen coconut oil to bowl and cut into mixture using a pastry cutter or 2 forks In a separate bowl, whisk together egg whites, egg, vanilla, honey Add wet ingredients to dry ingredients Mix until a dough comes together (if dough seems sticky, add in 1 tbs of oat flour at a time) Place dough onto parchment lined baking sheet Shape into a circle Sprinkle with remaining 1 tsp ground cinnamon Bake 15-18 minutes or until edges start to firm Remove from the oven and cut into 8 triangles (center will still seem undercooked, this is ok) Return to the oven for another 5-7 minutes Remove from the oven and give your scones one more pass through with the knife Separate the scones on the baking sheet Return to the oven and bake for 2 minutes Finish off with additional cinnamon/sugar, a drizzle of coconut butter or protein ‘frosting’ if desired', N'["High Protein Recipes","Snack Recipes","Breakfast Recipes"]', N'{"calories_kcal":"266","protein_g":"12","carbs_g":"32","fat_g":"10"}', 13800);
END
ELSE UPDATE dbo.MealSuggestions SET
    Title=N'High Protein Churro Scones Recipe', MealType=N'Breakfast', Description=N'Can''t find the perfect high protein snack to pair with your morning coffee? Try out this protein churro scone recipe as your coffee''s sweet counterpart.', CaloriesKcal=266, ProteinG=12, CarbsG=32, FatsG=10,
    SuggestedMonth=NULL, IsSystemDefault=1, SortOrder=10159, SourceUrl=N'https://www.muscleandstrength.com/recipes/churro-protein-scones', ImageUrl=N'https://cdn.muscleandstrength.com/sites/default/files/field/feature-image/recipe/churro-protein-scone-thumb.jpg', ServingSuggestion=N'Makes 8 Servings', ContentText=N'Preheat oven to 400 degrees F Line a baking sheet with parchment paper Combine oat flour, protein powder, baking powder, salt and 2 tsp cinnamon in a bowl Add frozen coconut oil to bowl and cut into mixture using a pastry cutter or 2 forks In a separate bowl, whisk together egg whites, egg, vanilla, honey Add wet ingredients to dry ingredients Mix until a dough comes together (if dough seems sticky, add in 1 tbs of oat flour at a time) Place dough onto parchment lined baking sheet Shape into a circle Sprinkle with remaining 1 tsp ground cinnamon Bake 15-18 minutes or until edges start to firm Remove from the oven and cut into 8 triangles (center will still seem undercooked, this is ok) Return to the oven for another 5-7 minutes Remove from the oven and give your scones one more pass through with the knife Separate the scones on the baking sheet Return to the oven and bake for 2 minutes Finish off with additional cinnamon/sugar, a drizzle of coconut butter or protein ‘frosting’ if desired', CategoriesJson=N'["High Protein Recipes","Snack Recipes","Breakfast Recipes"]', SourceMacrosJson=N'{"calories_kcal":"266","protein_g":"12","carbs_g":"32","fat_g":"10"}', ReadCount=13800
    WHERE MealSuggestionId=@ImportedMealSuggestionId;
