INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 12, N'OR ¼ cup nonfat greek yogurt + 2tbs vanilla protein powder + 2-3 tbs almond milk');
