DECLARE @ImportedMealSuggestionId UNIQUEIDENTIFIER;
SELECT TOP (1) @ImportedMealSuggestionId=MealSuggestionId FROM dbo.MealSuggestions
WHERE SourceUrl=N'https://www.muscleandstrength.com/recipes/chicken-protein-waffles' OR (SourceUrl IS NULL AND Title=N'High Protein Chicken & Waffles Recipe');
IF @ImportedMealSuggestionId IS NULL
BEGIN
    SET @ImportedMealSuggestionId=NEWID();
    INSERT INTO dbo.MealSuggestions
        (MealSuggestionId, Title, MealType, Description, CaloriesKcal, ProteinG, CarbsG, FatsG, SuggestedMonth, IsSystemDefault, SortOrder, SourceUrl, ImageUrl, ServingSuggestion, ContentText, CategoriesJson, SourceMacrosJson, ReadCount)
    VALUES (@ImportedMealSuggestionId, N'High Protein Chicken & Waffles Recipe', N'Breakfast', N'The two go hand in hand like weightlifting and gains! Top your breakfast with a little soul food with this delicious high protein chicken & waffles recipe!', 565, 65, 56, 9, NULL, 1, 10162, N'https://www.muscleandstrength.com/recipes/chicken-protein-waffles', N'https://cdn.muscleandstrength.com/sites/default/files/field/feature-image/recipe/protein-chicken-waffles-feature.jpg', N'Makes 2 Servings', N'Add chicken breast, milk and hot sauce to a Ziploc bag Shake well and place in the refrigerator overnight The next day, add your special k cereal to a food processor and blend into small pieces (conversely, you can add to a Ziploc back and crush by hand) Put the cereal, cornmeal, paprika, salt and pepper in a Ziploc bag Preheat oven to 400 degrees Line a baking sheet with parchment paper Remove chicken, one piece at a time, from the marinating bag and add to cereal mixture Shake until coated Repeat with all chicken Place coated chicken on baking sheet Bake for 20 minutes Reduce heat to 350 degrees and bake for an additional 15 minutes or until crispy While chicken is cooking, make waffles according to directions Serve chicken on top of waffles Add syrup and butter for a more authentic experience, if desired Notes: *You increase the protein content more by swapping the water for liquid eggwhites when making your waffles and/or increasing the amount of chicken used in the recipe', N'["High Protein Recipes","Breakfast Recipes"]', N'{"calories_kcal":"565","protein_g":"65","carbs_g":"56","fat_g":"9"}', 13500);
END
