DECLARE @ImportedMealSuggestionId UNIQUEIDENTIFIER;
SELECT TOP (1) @ImportedMealSuggestionId=MealSuggestionId FROM dbo.MealSuggestions
WHERE SourceUrl=N'https://www.muscleandstrength.com/recipes/bikini-booty-protein-smoothie1' OR (SourceUrl IS NULL AND Title=N'Jen Jewell''s Bikini Booty Protein Smoothie Recipe');
IF @ImportedMealSuggestionId IS NULL
BEGIN
    SET @ImportedMealSuggestionId=NEWID();
    INSERT INTO dbo.MealSuggestions
        (MealSuggestionId, Title, MealType, Description, CaloriesKcal, ProteinG, CarbsG, FatsG, SuggestedMonth, IsSystemDefault, SortOrder, SourceUrl, ImageUrl, ServingSuggestion, ContentText, CategoriesJson, SourceMacrosJson, ReadCount)
    VALUES (@ImportedMealSuggestionId, N'Jen Jewell''s Bikini Booty Protein Smoothie Recipe', N'Snack', N'Simple, delicious and high in protein, this super easy and quick smoothie recipe uses only 5 ingredients but still packs a solid dose of protein to keep muscles happy!', 295, 30, 27, 7, NULL, 1, 10175, N'https://www.muscleandstrength.com/recipes/bikini-booty-protein-smoothie1', N'https://cdn.muscleandstrength.com/sites/default/files/field/feature-image/recipe/bikini_booty.jpg', N'Make and serve whenever you want. Ideal for post workout!', N'Take one rounded scoop of Cellucor COR-Performance Whey Protein Vanilla (can substitute for any other COR-Performance flavors) and add into blender. Add your Greens supplement of choice into the blender. 2 cups of spinach can also be substituted here if you''d like. Mix in the tablespoon of chia seeds into the blender. If you''re not a fan of chia seeds you can substitute almond or peanut butter instead. Take the cup of frozen raspberries and add those in the blender. Add the cup of Almond milk and blend for 5-10 seconds and enjoy!', N'["Protein Shake Recipes","Vegetarian Recipes"]', N'{"calories_kcal":"295","protein_g":"30","carbs_g":"27","fat_g":"7"}', 12100);
END
