DECLARE @ImportedMealSuggestionId UNIQUEIDENTIFIER;
SELECT TOP (1) @ImportedMealSuggestionId=MealSuggestionId FROM dbo.MealSuggestions
WHERE SourceUrl=N'https://www.muscleandstrength.com/recipes/white-chocolate-strawberry-coconut-protein-truffles' OR (SourceUrl IS NULL AND Title=N'White Chocolate Strawberry Coconut Protein Truffles Recipe');
IF @ImportedMealSuggestionId IS NULL
BEGIN
    SET @ImportedMealSuggestionId=NEWID();
    INSERT INTO dbo.MealSuggestions
        (MealSuggestionId, Title, MealType, Description, CaloriesKcal, ProteinG, CarbsG, FatsG, SuggestedMonth, IsSystemDefault, SortOrder, SourceUrl, ImageUrl, ServingSuggestion, ContentText, CategoriesJson, SourceMacrosJson, ReadCount)
    VALUES (@ImportedMealSuggestionId, N'White Chocolate Strawberry Coconut Protein Truffles Recipe', N'Snack', N'Enjoying your sweets while staying on track with your fitness goals doesn’t get any easier (or tastier) with this protein-packed treat!', 87, 4, 8, 4, NULL, 1, 10176, N'https://www.muscleandstrength.com/recipes/white-chocolate-strawberry-coconut-protein-truffles', N'https://cdn.muscleandstrength.com/sites/default/files/field/feature-image/recipe/wcs_feature.jpg', N'Makes 20 truffles.', N'Mix together protein, oat flour, coconut flour and shredded coconut. Combine honey and coconut oil and heat in microwave until melted. Mix milk into oil/honey. Combine wet and dry ingredients (keep mixing – it will seem very dry at first, but put those arms to work and keep combining until a dough forms).* Cover your dough and chill for 30 minutes. Roll dough into desired size truffles. Roll truffles in melted white chocolate. Allow to set in refrigerator or freezer until white chocolate is hard. Notes *Some protein powders may require up to 1-2 additional tbs of milk. You can leave out the shredded coconut to reduce calories and fat. You can leave off the outside white chocolate coating to reduce carbs/calories/fat.', N'["Snack Recipes"]', N'{"calories_kcal":"87","protein_g":"4.2","carbs_g":"8.2","fat_g":"4.4"}', 11900);
END
ELSE UPDATE dbo.MealSuggestions SET
    Title=N'White Chocolate Strawberry Coconut Protein Truffles Recipe', MealType=N'Snack', Description=N'Enjoying your sweets while staying on track with your fitness goals doesn’t get any easier (or tastier) with this protein-packed treat!', CaloriesKcal=87, ProteinG=4, CarbsG=8, FatsG=4,
    SuggestedMonth=NULL, IsSystemDefault=1, SortOrder=10176, SourceUrl=N'https://www.muscleandstrength.com/recipes/white-chocolate-strawberry-coconut-protein-truffles', ImageUrl=N'https://cdn.muscleandstrength.com/sites/default/files/field/feature-image/recipe/wcs_feature.jpg', ServingSuggestion=N'Makes 20 truffles.', ContentText=N'Mix together protein, oat flour, coconut flour and shredded coconut. Combine honey and coconut oil and heat in microwave until melted. Mix milk into oil/honey. Combine wet and dry ingredients (keep mixing – it will seem very dry at first, but put those arms to work and keep combining until a dough forms).* Cover your dough and chill for 30 minutes. Roll dough into desired size truffles. Roll truffles in melted white chocolate. Allow to set in refrigerator or freezer until white chocolate is hard. Notes *Some protein powders may require up to 1-2 additional tbs of milk. You can leave out the shredded coconut to reduce calories and fat. You can leave off the outside white chocolate coating to reduce carbs/calories/fat.', CategoriesJson=N'["Snack Recipes"]', SourceMacrosJson=N'{"calories_kcal":"87","protein_g":"4.2","carbs_g":"8.2","fat_g":"4.4"}', ReadCount=11900
    WHERE MealSuggestionId=@ImportedMealSuggestionId;
DELETE FROM dbo.MealSuggestionIngredients WHERE MealSuggestionId=@ImportedMealSuggestionId;
