DELETE FROM dbo.MealSuggestionIngredients WHERE MealSuggestionId=@ImportedMealSuggestionId;
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 1, N'3 Apples');
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 2, N'9 Caramels');
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 3, N'3 tbsp. Chocolate Peanut Butter*');
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 4, N'3 tbsp. Plain Peanut Butter');
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 5, N'2 tsp. Coconut Oil');
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 6, N'Sprinkles (as desired)');
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 7, N'Straws (paper works best)');
DELETE FROM dbo.MealSuggestionInstructions WHERE MealSuggestionId=@ImportedMealSuggestionId;
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 1, N'Using a knife, cut “X” into top of apple');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 2, N'Stick the straw into the top of the apple where you made the “X”');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 3, N'Place apples on parchment paper');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 4, N'Melt caramels with 1 tsp water');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 5, N'Drizzle caramel over the top of each apple');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 6, N'Place in fridge to set');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 7, N'Add chocolate peanut butter and 1 tsp coconut oil to a ziplock bag and mix');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 8, N'Cut a small whole in the corner of the ziplock bag');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 9, N'Remove apples from refrigerator and drizzle with chocolate peanut butter');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 10, N'Place back in refrigerator');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 11, N'Add plain peanut butter and 1 tsp coconut oil to a second ziplock bag and mix');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 12, N'Cut a small whole in the corner of the ziplock bag');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 13, N'Drizzle peanut butter over chocolate layer');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 14, N'Add sprinkles, if desired');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 15, N'Place back in refrigerator to set');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 16, N'Enjoy!');
GO

SELECT
    (SELECT COUNT(*) FROM dbo.WorkoutSplits WHERE SourceUrl LIKE N'https://www.muscleandstrength.com/workouts/%' OR SourceUrl LIKE N'https://www.muscleandstrength.com/content/%') AS ImportedWorkouts,
    (SELECT COUNT(*) FROM dbo.DietPlans WHERE SourceUrl LIKE N'https://www.muscleandstrength.com/diet-plans/%') AS ImportedDietPlans,
    (SELECT COUNT(*) FROM dbo.MealSuggestions WHERE SourceUrl LIKE N'https://www.muscleandstrength.com/%') AS ImportedRecipes,
    (SELECT COUNT(*) FROM dbo.MealSuggestionIngredients i INNER JOIN dbo.MealSuggestions m ON m.MealSuggestionId=i.MealSuggestionId WHERE m.SourceUrl LIKE N'https://www.muscleandstrength.com/%') AS ImportedIngredients;
GO

COMMIT TRANSACTION;
GO
